<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Importação e exportação de despesas';require APPPATH.'views/admin/companies/layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_imports'.$q);$hidden=function(string $action)use($esc,$company_imports_csrf){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_imports_csrf" value="'.$esc($company_imports_csrf).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';}; ?>
<section class="company-settings-card"><h1>Importação e exportação de despesas</h1><p>Arquivos privados da empresa ativa. A importação cria novos registros locais, sem pagar despesas, adotar registros legados ou alterar despesas existentes.</p><?php if($error){?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><p><a href="<?= $esc($url()); ?>">Reabrir a tela</a></p><?php } ?>
<h2>Exportar despesas próprias</h2><p><a href="<?= $esc($url('?export=expenses&after='.(int)$expense_page['after'])); ?>">Baixar esta página em CSV privado (até 100 despesas)</a></p><p>O CSV contém moeda, base, tributo, total e estado por despesa, incluindo canceladas. Texto potencialmente interpretado como fórmula recebe apóstrofo. Use Próxima página para revisar e exportar os registros seguintes.</p>
<div class="table-responsive"><table class="table"><thead><tr><th>Número</th><th>Data</th><th>Descrição</th><th>Moeda</th><th>Total</th><th>Estado</th></tr></thead><tbody><?php foreach($expense_page['items'] as $row){?><tr><td><?= (int)$row['number']; ?></td><td><?= $esc($row['expense_date']); ?></td><td><?= $esc($row['description']); ?></td><td><?= $esc($row['currency']); ?></td><td><?= $esc(CompanyExpenses::money((int)$row['total_cents'])); ?></td><td><?= $row['state']==='recorded'?'Registrada':'Cancelada'; ?></td></tr><?php } ?></tbody></table></div><?php if($expense_page['next']!==null){?><a href="<?= $esc($url('?after='.$expense_page['next'])); ?>">Próxima página de despesas para exportação</a><?php } ?>
<?php if($batch){?><h2>Lote <?= $esc($batch['batch_id']); ?></h2><p>Estado: <?= $batch['state']==='committed'?'Confirmado':($batch['expired']?'Preview expirado':'Aguardando confirmação'); ?> · Preview válido até <?= $esc($batch['expires_at']); ?> UTC.</p><ul><?php foreach($batch['totals'] as $currency=>$total){?><li><?= $esc($currency.' '.$total); ?></li><?php } ?></ul><div class="table-responsive"><table class="table"><thead><tr><th>Linha</th><th>Descrição</th><th>Categoria</th><th>Cliente / projeto</th><th>Data</th><th>Moeda</th><th>Base</th><th>Tributo</th><th>Total</th></tr></thead><tbody><?php foreach($batch['items'] as $index=>$item){?><tr><td><?= $index+1; ?></td><td><?= $esc($item['input']['description']); ?></td><td><?= $esc($item['category_name']); ?></td><td><?= $esc($item['client_name'].' / '.$item['project_name']); ?></td><td><?= $esc($item['input']['date']); ?></td><td><?= $esc($item['input']['currency']); ?></td><td><?= $esc($item['input']['amount']); ?></td><td><?= $esc($item['tax']); ?></td><td><?= $esc($item['total']); ?></td></tr><?php } ?></tbody></table></div>
<?php if($batch['result']){?><p role="status">Lote confirmado. Despesas criadas:</p><ul><?php foreach($batch['result']['expense_ids'] as $id){?><li><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_expenses?expense='.(int)$id)); ?>">Despesa <?= (int)$id; ?></a></li><?php } ?></ul><?php }elseif(!$batch['expired']&&$can_import){?><?= form_open($url());$hidden('commit'); ?><input type="hidden" name="batch_id" value="<?= $esc($batch['batch_id']); ?>"><input type="hidden" name="revision" value="<?= $esc($batch['revision']); ?>"><p>Confirme somente após revisar todas as linhas. Categoria, cliente, projeto e permissões serão revalidados. Se qualquer linha falhar, o lote inteiro será revertido.</p><button type="submit" id="import-commit">Confirmar lote inteiro de despesas</button><?= form_close(); ?><?php } ?><?php } ?>
<?php if($can_import){?><h2>Gerar preview obrigatório</h2><p>Até 100 linhas e 256 KiB em UTF-8. CSV usa ponto e vírgula, cabeçalho exato abaixo e casas decimais com ponto. JSON usa uma lista de objetos com os mesmos campos. IDs devem pertencer a esta empresa; projeto exige o mesmo cliente selecionado. Moedas BRL, USD ou EUR. Fórmulas e campos desconhecidos são recusados.</p><pre><?= $esc(implode(';',CompanyImports::COLUMNS)); ?></pre><p>Cliente e projeto sem vínculo: <code>0</code>; observação vazia permitida. Alíquota adicional percentual entre 0 e 100. O preview expira após uma hora e não consome numeração.</p><?= form_open_multipart($url());$hidden('preview'); ?><label for="import-format">Formato</label><select id="import-format" class="form-control" name="format"><option value="csv">CSV (;)</option><option value="json">JSON</option></select><label for="import-file">Arquivo privado</label><input id="import-file" class="form-control" type="file" name="source_file" accept=".csv,.json" required><button type="submit">Validar e visualizar antes de importar</button><?= form_close(); ?>
<h2>Seus lotes recentes nesta empresa</h2><ul><?php foreach($batches as $row){?><li><a href="<?= $esc($url('?batch='.$row['batch_id'])); ?>"><?= $esc($row['batch_id']); ?></a> · <?= (int)$row['row_count']; ?> linhas · <?= $esc($row['state']==='committed'?'Confirmado':'Preview'); ?> · <?= $esc($row['created_at']); ?> UTC</li><?php } ?></ul><?php } ?></section>
